<?php
require_once __DIR__.'/../includes/auth.php'; require_once __DIR__.'/../includes/helpers.php';
$eventType=$_GET['event']??'Transferred'; $valid=['Transferred','Terminated','Recruited']; if(!in_array($eventType,$valid,true))$eventType='Transferred';
require_role(['Admin','HR Admin']); $pdo=db();
$pdo->exec("CREATE TABLE IF NOT EXISTS employee_events (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, employee_id INT UNSIGNED NOT NULL, event_type ENUM('Transferred','Terminated','Recruited') NOT NULL, effective_date DATE NOT NULL, destination_branch VARCHAR(120) NULL, notes TEXT NULL, created_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX idx_event_type(event_type), FOREIGN KEY(employee_id) REFERENCES employees(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
$error='';
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf($_POST['csrf']??null); try {
 $employee=(int)($_POST['employee_id']??0);$date=$_POST['effective_date']??date('Y-m-d');$branch=trim((string)($_POST['destination_branch']??''));$notes=trim((string)($_POST['notes']??''));
 $chk=$pdo->prepare('SELECT id FROM employees WHERE id=?');$chk->execute([$employee]);if(!$chk->fetch())throw new RuntimeException('Select a valid employee.');
 $pdo->beginTransaction();$st=$pdo->prepare('INSERT INTO employee_events(employee_id,event_type,effective_date,destination_branch,notes,created_by) VALUES(?,?,?,?,?,?)');$st->execute([$employee,$eventType,$date,$eventType==='Transferred'?$branch:null,$notes,current_user()['id']??null]);
 if($eventType==='Terminated')$pdo->prepare("UPDATE employees SET status='Terminated' WHERE id=?")->execute([$employee]);
 if($eventType==='Transferred' && $branch!=='')$pdo->prepare('UPDATE employees SET branch=? WHERE id=?')->execute([$branch,$employee]);
 if($eventType==='Recruited')$pdo->prepare("UPDATE employees SET status='Active' WHERE id=?")->execute([$employee]);$pdo->commit();redirect($_SERVER['PHP_SELF'].'?event='.urlencode($eventType).'&saved=1');
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e->getMessage();}}
$employees=$pdo->query('SELECT id,employee_code,full_name FROM employees ORDER BY full_name')->fetchAll();$st=$pdo->prepare('SELECT ev.*,e.employee_code,e.full_name,e.department,e.position,e.branch FROM employee_events ev JOIN employees e ON e.id=ev.employee_id WHERE ev.event_type=? ORDER BY ev.effective_date DESC,ev.id DESC');$st->execute([$eventType]);$rows=$st->fetchAll();
$title=$eventType.' Employees';require __DIR__.'/../includes/header.php'; ?>
<div class="page-head"><div><h2><?=e($title)?></h2><p>Record and review employee <?=strtolower(e($eventType))?> history.</p></div></div>
<?php if($error): ?><div class="card"><p><?=e($error)?></p></div><?php endif; ?><?php if(isset($_GET['saved'])): ?><div class="card"><p>Employee event saved successfully.</p></div><?php endif; ?>
<div class="card"><h3>Record <?=e($eventType)?> event</h3><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Employee</label><select name="employee_id" required><option value="">Choose employee</option><?php foreach($employees as $emp): ?><option value="<?=(int)$emp['id']?>"><?=e($emp['employee_code'].' — '.$emp['full_name'])?></option><?php endforeach; ?></select><label>Effective date</label><input type="date" name="effective_date" required value="<?=e(date('Y-m-d'))?>"><?php if($eventType==='Transferred'): ?><label>Destination branch</label><input name="destination_branch" required maxlength="120" placeholder="Enter destination branch"><?php endif; ?><label>Notes</label><textarea name="notes" rows="3" placeholder="Reason or additional details"></textarea><button type="submit">Save event</button></form></div>
<div class="card"><h3><?=e($eventType)?> history (<?=count($rows)?>)</h3><div class="table-wrap"><table><thead><tr><th>Date</th><th>Employee code</th><th>Name</th><th>Department</th><th>Position</th><th>Branch</th><th>Notes</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="7">No <?=strtolower(e($eventType))?> events recorded yet.</td></tr><?php endif; ?><?php foreach($rows as $r): ?><tr><td><?=e($r['effective_date'])?></td><td><?=e($r['employee_code'])?></td><td><?=e($r['full_name'])?></td><td><?=e($r['department'])?></td><td><?=e($r['position'])?></td><td><?=e($r['destination_branch']?:$r['branch'])?></td><td><?=e($r['notes']??'')?></td></tr><?php endforeach; ?></tbody></table></div></div><?php require __DIR__.'/../includes/footer.php'; ?>